/**
 * WHY THIS FILE EXISTS
 *
 * Replays every case of fixtures/evaluation/*.json (generated by scripts/gen_fixtures.py from
 * hyphaeon/evaluation.py) against src/evaluate.js — `load_prediction_csv`, `load_meme_json`,
 * `_roc_auc`, `_correlations`, `evaluate_files` and its two error cases — at the fixture classes:
 * exact for counts, confusion matrices, site lists and messages, 1e-9 for correlations and AUC.
 * The inputs are read from fixtures/evaluation/inputs/ and handed over as {name, text} pairs, so
 * the report and the messages come out with the basenames the fixtures were reduced to.
 *
 * The fixtures exercise the loaders on well-formed files. The parser semantics the port
 * reproduces — Python's csv module, float(), int(), html.unescape, repr in messages — are checked
 * against test/data/evaluate/python_formatting.json, which the standard library itself produced
 * (see test/data/evaluate/gen.py), mostly THROUGH the public loaders so that what is pinned is the
 * behaviour a user can reach.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import {
	EvaluationError,
	loadPredictionCsv,
	loadMemeJson,
	matchGeneFiles,
	correlations,
	rocAuc,
	confusion,
	ppv,
	fpr,
	thresholdMetrics,
	evaluatePairs,
	evaluateDirectories,
	evaluateFiles,
	formatTextReport,
	parseCsvRows,
	dictReaderRows,
	normalizedHeader,
} from '../src/evaluate.js';
import { evaluateJson } from '../src/writers.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..');
const FIX = join(ROOT, 'fixtures', 'evaluation');
const loadFixture = (name) => JSON.parse(readFileSync(join(FIX, name), 'utf8'));
const input = (name) => readFileSync(join(FIX, 'inputs', name), 'utf8');
const file = (name) => ({ name, text: input(name) });
const ref = JSON.parse(readFileSync(join(HERE, 'data', 'evaluate', 'python_formatting.json'), 'utf8'));

/** A Map<number, record> as the fixture's string-keyed dict. */
function mapToObject(map) {
	const out = {};
	for (const [k, v] of map) out[String(k)] = v;
	return out;
}

/** Deep comparison at the fixture class: non-integer numbers within `tol`, everything else exact. */
function expectClose(got, want, tol, path = 'result') {
	if (typeof want === 'number' && !Number.isInteger(want)) {
		expect(typeof got, path).toBe('number');
		expect(Math.abs(got - want), `${path}: got ${got} want ${want}`).toBeLessThanOrEqual(tol);
	} else if (Array.isArray(want)) {
		expect(Array.isArray(got), path).toBe(true);
		expect(got.length, path).toBe(want.length);
		want.forEach((w, i) => expectClose(got[i], w, tol, `${path}[${i}]`));
	} else if (want !== null && typeof want === 'object') {
		expect(got !== null && typeof got === 'object', path).toBe(true);
		expect(Object.keys(got), `${path} keys`).toEqual(Object.keys(want));
		for (const k of Object.keys(want)) expectClose(got[k], want[k], tol, `${path}.${k}`);
	} else {
		expect(got, path).toEqual(want);
	}
}

