describe('fixtures/evaluation/roc_auc.json and correlations.json (evaluation.py:263-283)', () => {
	for (const c of loadFixture('roc_auc.json')) {
		it(`roc_auc ${c.name} (${c.tolerance})`, () => {
			const got = rocAuc(c.inputs.labels, c.inputs.scores);
			if (c.outputs.auc === null) expect(got).toBeNaN();
			else expect(Math.abs(got - c.outputs.auc)).toBeLessThanOrEqual(c.tolerance === 'exact' ? 0 : 1e-13);
		});
	}
	for (const c of loadFixture('correlations.json')) {
		it(`correlations ${c.name} (${c.tolerance})`, () => {
			const { pearson, spearman } = correlations(c.inputs.predicted, c.inputs.observed);
			if (c.outputs.pearson_r === null) {
				expect(pearson).toBeNull();
				expect(spearman).toBeNull();
			} else {
				expect(Math.abs(pearson - c.outputs.pearson_r)).toBeLessThanOrEqual(1e-13);
				expect(Math.abs(spearman - c.outputs.spearman_rho)).toBeLessThanOrEqual(1e-13);
			}
		});
	}
});

